"""Login page object - generated by TestAutomationScriptGenerator from login.csv.

Every locator is a placeholder: replace each value marked "TODO: confirm selector" with the real
selector (prefer data-testid or role-based selectors). Keep raw selectors out of the tests.
"""

from core.base_page import BasePage


class LoginGeneratedPage(BasePage):
    """Page object for the login feature."""

    USERNAME_INPUT = "[data-testid='username']"  # TODO: confirm selector
    PASSWORD_INPUT = "[data-testid='password']"  # TODO: confirm selector
    LOGIN_BUTTON = "[data-testid='login']"  # TODO: confirm selector
    ERROR_MESSAGE = "[data-testid='error-message']"  # TODO: confirm selector
    COUNTRY_SELECT = "[data-testid='country']"  # TODO: confirm selector
    REMEMBER_ME_CHECKBOX = "[data-testid='remember-me']"  # TODO: confirm selector
    DASHBOARD = "[data-testid='dashboard']"  # TODO: confirm selector

    def open(self, base_url: str, path: str = "") -> None:
        """Open this page relative to the environment base URL."""
        self.navigate(base_url.rstrip("/") + path)

    def enter_username(self, value: str) -> None:
        self.fill(self.USERNAME_INPUT, value)

    def enter_password(self, value: str) -> None:
        self.fill(self.PASSWORD_INPUT, value)

    def click_login_button(self) -> None:
        self.click(self.LOGIN_BUTTON)

    def get_error_message_text(self) -> str:
        return self.text(self.ERROR_MESSAGE)

    def select_country(self, value: str) -> None:
        self.select_option(self.COUNTRY_SELECT, value)

    def click_remember_me_checkbox(self) -> None:
        self.click(self.REMEMBER_ME_CHECKBOX)

    def is_dashboard_visible(self) -> bool:
        return self.is_visible(self.DASHBOARD)
